def copy_existing_fee_payments(apps, schema_editor):
    AccountingSettings = apps.get_model("accounting", "AccountingSettings")
    CashTransaction = apps.get_model("accounting", "CashTransaction")
    Payment = apps.get_model("payments", "Payment")

    school_ids = (
        Payment.objects.exclude(method="online")
        .values_list("school_id", flat=True)
        .distinct()
    )
    for school_id in school_ids:
        payments = list(
            Payment.objects.filter(school_id=school_id)
            .exclude(method="online")
            .select_related(
                "student_fee__student__school_class",
                "student_fee__structure",
            )
            .order_by("paid_at", "id")
        )
        if not payments:
            continue
        first_date = min(django.utils.timezone.localdate(p.paid_at) for p in payments)
        settings, _ = AccountingSettings.objects.get_or_create(
            school_id=school_id,
            defaults={"opening_date": first_date},
        )
        number = settings.last_receipt_number
        for payment in payments:
            account_type = (
                "cash" if payment.method == "cash" else "bank"
            )
            number += 1
            fee = payment.student_fee
            school_class = fee.student.school_class
            class_label = (
                f"{school_class.name} - {school_class.section}"
                if school_class.section
                else school_class.name
            )
            CashTransaction.objects.get_or_create(
                source_payment_id=payment.pk,
                defaults={
                    "school_id": school_id,
                    "voucher_no": f"RV-{number:06d}",
                    "entry_date": django.utils.timezone.localdate(payment.paid_at),
                    "transaction_type": "receipt",
                    "account_type": account_type,
                    "category": "student_fees",
                    "party": fee.student.name,
                    "amount": payment.amount,
                    "reference": payment.reference or payment.receipt_no,
                    "description": (
                        f"{fee.structure.title} | {fee.student.student_id} | "
                        f"{class_label}"
                    ),
                    "source": "student_fee",
                    "created_by_id": payment.received_by_id,
                },
            )
        settings.last_receipt_number = number
        settings.save(update_fields=["last_receipt_number"])


